# 否定响应矩阵：服务, 异常载荷, 预期 NRC, 说明
NRC_CASES = [
    (0x22, b"\xFF\xFF", 0x31, "$22 读不存在的 DID → requestOutOfRange"),
    (0x10, b"\x05",     0x12, "$10 子功能 0x05 不支持 → serviceNotSupported"),
    (0x2E, b"\xF1\x90", 0x33, "未解锁写受保护 DID → securityAccessDenied"),
    (0x27, b"\x02\x00", 0x35, "未先取 seed 直接发 key → invalidKey"),
]

@pytest.mark.parametrize("sid,payload,exp_nrc,desc", NRC_CASES)
