    assert resp.nrc == exp_nrc, f"{desc}: NRC {resp.nrc:02X}≠预期 {exp_nrc:02X}

# uds_helpers.py —— 诊断自动化常用工具库（全员复用，用例只写断言）
from functools import wraps

NRC_NAMES = {
    0x12: "serviceNotSupported",
    0x13: "incorrectMessageLengthOrInvalidFormat",
    0x22: "conditionsNotCorrect",
    0x31: "requestOutOfRange",
    0x33: "securityAccessDenied",
    0x35: "invalidKey",
    0x36: "exceedNumberOfAttempts",
    0x37: "requiredTimeDelayNotExpired",
    0x78: "requestCorrectlyReceived-ResponsePending",
    0x7E: "subFunctionNotSupportedInActiveSession",
    0x7F: "serviceNotSupportedInActiveSession",
}

def nrc_name(nrc):
    return NRC_NAMES.get(nrc, f"unknown(0x{nrc:02X})")

def expect_positive(resp, ctx):
    assert resp.service_id != 0x7F, f"{ctx}: 预期肯定响应，却得否定 NRC={nrc_name(resp.nrc)}"
    return resp.data

def expect_nrc(resp, nrc, ctx):
    assert resp.service_id == 0x7F, f"{ctx}: 预期否定响应(0x7F)，却得肯定响应"
    assert resp.nrc == nrc, f"{ctx}: NRC {nrc_name(resp.nrc)}≠预期 {nrc_name(nrc)}"

def retry_on_pending(fn, times=3):
    """ECU 忙时回 0x78(RCRRP)，封装自动重试直到拿到真响应"""
    for _ in range(times):
        resp = fn()
        if getattr(resp, "nrc", None) != 0x78:
            return resp
    raise TimeoutError("连续收到 RCRRP，ECU 长时间忙")

class session_scope:
    """上下文管理器：进入指定会话，退出时复位回默认会话（测试隔离）"""
    def __init__(self, ecu, session):
        self.ecu, self.session = ecu, session
    def __enter__(self):
        self.ecu.diagnostic_session_control(self.session)
        return self.ecu
    def __exit__(self, *exc):
        self.ecu.ecu_reset(0x01)   # 复位回默认会话，避免污染后续用例

_did_cache = {}
def read_did_cached(ecu, did):
    """相同用例内重复读同一 DID 时，命中缓存避免多余总线请求"""
    if did in _did_cache:
        return _did_cache[did]
    resp = ecu.read_data_by_identifier(did)
    data = expect_positive(resp, f"读DID {did:04X}")
    _did_cache[did] = data
    return data
